1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
69			if err != nil {
70				return sub, err
71			}
72			if !paid {
73				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
74					return sub, err
75				}
76			}
77		}
78		return sub, nil
79	}
80	
81	// UpdateInput changes a subscription; nil fields stay as they are.
82	type UpdateInput struct {
83		PlanID   *string
84		Quantity *int
85	}
86	
87	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
88	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
89		if in.PlanID != nil {
90			p, ok := s.Store.Plan(orgID, *in.PlanID)
91			if !ok {
92				return store.Subscription{}, store.ErrNotFound
93			}
94			if !p.Active {
95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
145	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
146	// due. RenewDue returns how many subscriptions it renewed or canceled.
147	func (s *Service) RenewDue(ctx context.Context) (int, error) {
148		now := s.Clock.Now()
149		n := 0
150		for _, sub := range s.Store.DueSubscriptions(now) {
151			if err := ctx.Err(); err != nil {
152				return n, err
153			}
154			if err := s.renew(ctx, sub, now); err != nil {
155				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
156			}
157			n++
158		}
159		return n, nil
160	}
161	
162	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
163		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
164		if !ok {
165			return store.ErrNotFound
166		}
167		if sub.CancelAtPeriodEnd {
168			end := sub.CurrentPeriodEnd
169			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
170				x.Status, x.CanceledAt = store.Canceled, &end
171				return nil
172			})
173			if err == nil {
174				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
175			}
176			return err
177		}
178		start := now
179		end := billing.AddInterval(start, plan.Interval)
180		paid := true
181		var err error
182		switch {
183		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
184			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
185		case plan.UsageType == store.Licensed:
186			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
187		}
188		if err != nil {
189			return err
190		}
191		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
192			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
193			if paid {
194				x.Status = store.Active
195			} else {
196				x.Status = store.PastDue
197			}
198			return nil
199		})
200		if err != nil {
201			return err
202		}
203		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
204		return nil
205	}
206	
207	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
208	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
209	// payment method stays open and counts as paid here (it is paid by hand).
210	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
211		var lines []store.Line
212		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
213		switch plan.UsageType {
214		case store.Licensed:
215			if plan.UnitAmount > 0 {
216				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
217			}
218		case store.Metered:
219			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
220				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
221			}
222		}
223		ps, pe := start, end
224		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
225			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
226		if err != nil {
227			return false, err
228		}
229		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
230		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
231		var decline *payments.DeclineError
232		switch {
233		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
234			return true, nil
235		case errors.As(err, &decline):
236			return false, nil
237		default:
238			return false, err
239		}
240	}
241	
242	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
243		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
244			x.Status = st
245			return nil
246		})
247		if err == nil {
248			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
249		}
250		return sub, err
251	}
252	
253	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
254		if s.Publisher != nil {
255			_ = s.Publisher.Publish(ctx, orgID, typ, data)
256		}
257	}
