// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. A change that raises the subscription's value (its plan's unit amount
// times its quantity) is an upgrade: it applies at once and is prorated on a new invoice for the current period. A change
// that lowers it is a downgrade: it becomes pending and applies at the next renewal. A change that keeps the value applies at
// once and bills nothing. A trialing subscription changes at once and bills nothing.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	var next store.Plan
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
		next = p
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	old, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if in.PlanID == nil {
		next = old
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	if old.Currency != next.Currency || old.Interval != next.Interval || old.UsageType == store.Metered || next.UsageType == store.Metered {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	qty := cur.Quantity
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	if qty <= 0 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	oldValue, newValue := old.UnitAmount*int64(cur.Quantity), next.UnitAmount*int64(qty)
	same := next.ID == cur.PlanID && qty == cur.Quantity
	trialing := cur.Status == store.Trialing
	upgrade := !same && !trialing && newValue > oldValue
	downgrade := !same && !trialing && newValue < oldValue

	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			pid, pq := next.ID, qty
			x.PendingPlanID, x.PendingQuantity = &pid, &pq
